// This test pins the pipeline, not the price: it drives the
// internal steps in order and asserts intermediate state.
public class FareCalculatorTests
{
    [Fact]
    public void DiscountPipeline_SetsEachIntermediateField()
    {
        var calculator = new FareCalculator();
        calculator.AddLeg("SYD-MEL", 89.00m);
        calculator.AddLeg("MEL-HBA", 61.00m);

        calculator.RecalculateBaseFare();
        Assert.Equal(150.00m, calculator.BaseFareSoFar);

        calculator.ApplySaverDiscount();
        Assert.Equal(0.10m, calculator.DiscountRateApplied);
        Assert.Single(calculator.DiscountAuditLog);

        Assert.Equal(135.00m, calculator.FareAfterDiscount);
    }
}

// Fold the three steps into one method — behavior identical —
// and this test does not fail: it stops compiling.

