// The same rules pinned at the Target Interface: legs in, one
// observable fare out. The pipeline is free to change shape.
public class FareCalculatorTests
{
    private static IFareCalculator Create() => new FareCalculator();

    [Fact]
    public void TwoLegsReaching150_EarnTheSaverDiscount()
    {
        IFareCalculator calculator = Create();
        calculator.AddLeg("SYD-MEL", 89.00m);
        calculator.AddLeg("MEL-HBA", 61.00m);

        Assert.Equal(135.00m, calculator.TotalFare());
    }

    [Fact]
    public void ASingleShortLeg_PaysTheFullFare()
    {
        IFareCalculator calculator = Create();
        calculator.AddLeg("SYD-MEL", 89.00m);

        Assert.Equal(89.00m, calculator.TotalFare());
    }
}

// Merge the steps, rename every field, delete the audit log —
// these tests stay green as long as the fares stay right.

