// The policy reads the real clock, so the test can only assert
// "roughly" — it re-implements the rule and hopes nothing ticks
// across a boundary mid-run.
public class TrialPeriodTests
{
    [Fact]
    public void Trial_LastsFourteenDays()
    {
        // Stamps DateTime.UtcNow inside its constructor.
        var trial = new TrialPeriod();

        Assert.False(trial.HasExpired());

        // Expiry cannot be reached without waiting 14 real days,
        // so the "test" repeats the arithmetic instead:
        var expected = DateTime.UtcNow.AddDays(14);
        Assert.True(
            (trial.ExpiresAtUtc - expected).Duration()
                < TimeSpan.FromSeconds(5));
    }
}

// A tolerance assertion is the tell: a volatile dependency is
// leaking through the boundary, out of the test's control.

modelExamples.after:
// Time enters through the boundary, so the Test Suite owns it:
// a fake clock drives the trial to the exact moment that matters.
public class TrialPeriodTests
{
    private sealed class FakeClock : IClock
    {
        public DateTime UtcNow { get; set; }
    }

    [Fact]
    public void Trial_ExpiresTheInstantFourteenDaysPass()
    {
        var clock = new FakeClock
        {
            UtcNow = new DateTime(2026, 3, 1, 9, 0, 0,
                DateTimeKind.Utc),
        };
        var trial = new TrialPeriod(clock);

        clock.UtcNow = clock.UtcNow.AddDays(14);
        Assert.False(trial.HasExpired());

        clock.UtcNow = clock.UtcNow.AddSeconds(1);
        Assert.True(trial.HasExpired());
    }
}

// No tolerance, no waiting: the expiry boundary itself — the
// last legal second and the first expired one — is now pinned.

modelExamples.before:
// One test, every rule at once. When it goes red, which rule
// broke? The name cannot tell you — it claims everything.
public class BaggageFeeTests
{
    [Fact]
    public void Fees_WorkCorrectly()
    {
        var fees = new BaggageFees();

        Assert.Equal(0m, fees.FeeFor(bags: 1, tier: "none"));
        Assert.Equal(0m, fees.FeeFor(bags: 1, tier: "gold"));
        Assert.Equal(35m, fees.FeeFor(bags: 2, tier: "none"));
        Assert.Equal(0m, fees.FeeFor(bags: 2, tier: "gold"));
        Assert.Equal(70m, fees.FeeFor(bags: 3, tier: "none"));
        Assert.Equal(35m, fees.FeeFor(bags: 3, tier: "gold"));
        Assert.Equal(105m, fees.FeeFor(bags: 4, tier: "none"));
        Assert.Throws<ArgumentOutOfRangeException>(
            () => fees.FeeFor(bags: -1, tier: "none"));
    }
}

// Eight claims share one name and one failure message. The
// first broken Assert also hides every claim after it.

modelExamples.after:
// One rule per test, named as the rule. A red run now reads as
// a spec violation: the failing name states what broke.
public class BaggageFeeTests
{
    [Fact]
    public void TheFirstBag_FliesFree() =>
        Assert.Equal(0m, new BaggageFees().FeeFor(1, "none"));

    [Fact]
    public void EachExtraBag_CostsThirtyFive() =>
        Assert.Equal(70m, new BaggageFees().FeeFor(3, "none"));

    [Fact]
    public void GoldMembers_GetTheirSecondBagFree() =>
        Assert.Equal(0m, new BaggageFees().FeeFor(2, "gold"));

    [Fact]
    public void GoldMembers_PayFromTheirThirdBag() =>
        Assert.Equal(35m, new BaggageFees().FeeFor(3, "gold"));

    [Fact]
    public void NegativeBagCounts_AreRejected() =>
        Assert.Throws<ArgumentOutOfRangeException>(
            () => new BaggageFees().FeeFor(-1, "none"));
}

