exercises.targetInterfaceCode:
public interface IBasketPricer
{
    // Accumulates quantity * unitPrice per call; the same sku may
    // be added more than once. Negative unitPrice or quantity < 1:
    // ArgumentOutOfRangeException.
    void AddItem(string sku, decimal unitPrice, int quantity);

    // Subtotal minus the tier discount — 5% off subtotals of 100m
    // or more, 10% off 250m or more — rounded to 2 decimals away
    // from zero. Empty basket: 0m.
    decimal Total();
}

public interface IClock
{
    // The current UTC moment; the Test Suite supplies a fake.
    DateTime UtcNow { get; }
}

public interface IRateLimiter
{
    // True — and the call is recorded — while fewer than 5 calls
    // for this key were recorded in the last 60 seconds (a call
    // ages out once it is MORE than 60 seconds old). A refused
    // call is never recorded. Keys are independent.
    bool TryPass(string key);
}
